import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.CTeY_0bQ.js";const p=JSON.parse('{"title":"0008 能力按来源分层，平台插件作为适配器的一部分","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0008-capability-sources-and-platform-plugin.md","filePath":"reference/adr/0008-capability-sources-and-platform-plugin.md","lastUpdated":null}'),l={name:"reference/adr/0008-capability-sources-and-platform-plugin.md"};function r(d,e,s,n,c,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<div><h1 id="_0008-能力按来源分层-平台插件作为适配器的一部分" tabindex="-1">0008 能力按来源分层，平台插件作为适配器的一部分 <a class="header-anchor" href="#_0008-能力按来源分层-平台插件作为适配器的一部分" aria-label="Permalink to &quot;0008 能力按来源分层，平台插件作为适配器的一部分&quot;">​</a></h1><ul><li>状态：提议</li><li>日期：2026-10-29</li><li>关联：<a href="./0002-two-orchestration-modes">ADR 0002</a>、<a href="./0003-generate-once-then-lock">ADR 0003</a>、<a href="./0006-deterministic-engine-platform-capabilities">ADR 0006</a>、<a href="./0007-one-install-many-repos">ADR 0007</a></li><li>详见：<a href="https://github.com/yiyisf/laoshi/blob/main/docs/design/dsh-adapter.md" target="_blank" rel="noreferrer">dsh-adapter.md</a>、<a href="https://github.com/yiyisf/laoshi/blob/main/docs/discovery/dsh/report.md" target="_blank" rel="noreferrer">dsh 摸底报告</a></li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>现有的能力契约（<a href="./../contracts/agent-runtime">agent-runtime.md</a>）是从 Paseo 的接口逐个方法整理出来的，只区分&quot;有&quot;和&quot;没有&quot;，没有的能力一律降级为 <code>null</code>。</p><p>用 DeepSeek Harness（dsh）检验时发现，&quot;没有&quot;其实分好几种情况：</p><ul><li>平台有这项能力，但外部 API 调不到，host 内的插件可以调到。例如 dsh 在对话下创建子 agent、创建定时任务、回答审批。</li><li>平台根本没有这项能力，但 laoshi 可以自己实现，而且这份实现适用于所有平台。例如服务管理、<code>git worktree</code>、本机调度。</li><li>确实做不到。例如订阅额度。</li></ul><p>如果把前两种都当成&quot;没有&quot;来降级，dsh 上就达不到 Paseo 的体验；如果让每个适配器各自去补，同一份实现会被重复写好几遍。</p><p>另外，Paseo 的审批由人在 Paseo 界面里完成，引擎只负责轮询。而 dsh（以及内部平台的 HITL，见 <a href="https://github.com/yiyisf/laoshi/blob/main/docs/design/internal-platform-adapter.md" target="_blank" rel="noreferrer">internal-platform-adapter §4</a>）需要有一方主动作答。现有契约里没有&quot;作答&quot;这项能力。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ol><li><p><strong>每项能力标明来源</strong>，按以下顺序选用：</p><ul><li><code>platform</code>：平台原生提供；</li><li><code>plugin</code>：laoshi 为该平台写的插件，运行在平台进程内；</li><li><code>builtin</code>：laoshi 内置实现，与平台无关；</li><li><code>none</code>：降级，行为同契约中的&quot;现状&quot;一栏。</li></ul><p>运行时层负责按这个顺序选择，调用点不再各写各的降级。<code>laoshi doctor</code> 的能力矩阵显示每项能力实际使用的来源。&quot;和 Paseo 一样的体验&quot;的判断标准是：矩阵中除了契约允许缺失的项以外，没有 <code>none</code>。</p></li><li><p><strong>平台插件是适配器的正式组成部分。</strong> 适配器由运行时、对话通道、词汇表、体检组成，平台允许时再加一个插件。插件只提供能力（创建子 agent、预约、审批、凭据），<strong>不编排流程</strong>；顺序、轮数、质量门仍然只在引擎里（ADR 0006）。插件和运行时一起锁定版本（ADR 0003）。</p></li><li><p><strong>以下能力由 laoshi 内置实现</strong>，适配器可以用平台原生能力替换：</p><ul><li>worktree（<code>git worktree</code>）；</li><li>服务管理（读取代码库配置中的服务，分配端口，健康检查，保留输出）；</li><li>本机调度器（平台和插件都没有定时任务时，到点调用 <code>notifyAgent</code>）。</li></ul><p>Paseo 适配器继续使用 Paseo 自己的工作区、<code>paseo.json</code> 服务和定时任务。</p></li><li><p><strong>审批作为一项正式能力</strong>：</p><ul><li>契约新增可选能力&quot;回答待处理的请求&quot;，以及项目级的<strong>审批策略</strong>（允许、拒绝、交给人）。</li><li>策略没有写到的请求一律交给人；不能默认允许。</li><li>只处理 laoshi 步骤的请求，不干预使用者自己的会话。</li><li>交给人时，在对话里提醒&quot;某个步骤在等批准&quot;。</li></ul><p>这同时回答了内部平台适配器 §4 的问题：方案 B（由 laoshi 转交）对应 <code>plugin</code> 或 <code>platform</code> 来源，方案 A（人在平台界面里处理）就是交给人的那一支。</p></li><li><p><strong>契约修订，与实现一起提交</strong>（这里只定方向，不单独先改契约文件）：</p><ul><li><code>listPaseoProfiles</code> 改名为 <code>listProfiles</code>；</li><li><code>attachAgent</code> 的语义改为&quot;恢复步骤会话&quot;：能恢复原会话就恢复，不能就按结果文件重做这一步；</li><li>引入 agent 事件模型（消息、工具调用、工具结果、权限请求、用量、回合结束），由核心从事件推导 <code>wait</code>、<code>recentActivity</code>、<code>runningTool</code>、<code>toolCalls</code> 和用量，适配器只需提供事件。轮询式平台由解释器把状态变化转换成事件；</li><li>把 <code>verifyOrigin</code>、<code>notifyAgent</code>、定时消息、步骤显示在对话下等能力归入单独的&quot;对话通道&quot;，便于组合，例如&quot;平台运行时 + 外部通知器通道&quot;。</li></ul></li><li><p><strong>dsh 适配器的形态是&quot;外部引擎 + laoshi dsh 插件&quot;</strong>：</p><ul><li>引擎通过 web host 的 <code>/api</code> 创建、下发、取消、列出、追问会话；</li><li>插件负责在对话下创建子 agent、创建定时任务、回答审批，以及引擎的认证。</li><li><code>dsh headless</code> 和 <code>dsh acp</code> 不作为 dsh 的主路径：步骤在 web 界面里看不到。它们可以作为&quot;无头 CLI 运行时&quot;（M3）的后端。</li></ul></li></ol><h2 id="理由" tabindex="-1">理由 <a class="header-anchor" href="#理由" aria-label="Permalink to &quot;理由&quot;">​</a></h2><ul><li>摸底中，dsh 所有影响体验的能力（对话下的子 agent、定时消息、插件审批）都已实测可用，只是要经由插件。不把插件当作正式来源，这些能力就只能放弃。</li><li>worktree、服务和调度与平台无关，在 req-kit 中原本就由 Paseo 代劳；换到其他平台时，没有理由由每个适配器各写一遍。</li><li>只有声明了来源，<code>doctor</code> 才能如实说明&quot;这项能力由谁提供&quot;，使用者也才能判断体验差在哪里。</li></ul><h2 id="待验证" tabindex="-1">待验证 <a class="header-anchor" href="#待验证" aria-label="Permalink to &quot;待验证&quot;">​</a></h2><ol><li>内网真实模型下的 <code>evals/</code> 端到端评估，以及&quot;夸大&quot;指标为零。</li><li>事件模型能否同样覆盖 Paseo（时间线）和内部平台（轮询状态），从而让三个适配器共用同一套一致性测试。</li></ol><p>已验证或已决定：</p><ul><li>子会话在 host 重启后的冷恢复（<code>attachAgent</code>），见摸底包自测 P12。</li><li>插件与引擎之间：<strong>插件代为调用</strong>（2026-11-01 决定），引擎只通过本地通道（socket / 命名管道 + 令牌）调用插件，不调用 dsh 的 <code>/api</code>（<a href="https://github.com/yiyisf/laoshi/blob/main/docs/design/dsh-adapter.md" target="_blank" rel="noreferrer">dsh-adapter §4</a>）。M4b 原型按此实现，在真实 dsh 上跑通了 quick 档流水线（<a href="./../../guide/dsh">adapters/dsh</a>）。</li><li>内网真实模型配合 dsh：模型接入、按结果文件约定完成步骤任务，见内网摸底包第三次运行（<a href="https://github.com/yiyisf/laoshi/blob/main/docs/discovery/dsh/report.md" target="_blank" rel="noreferrer">摸底报告</a>）。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li><a href="./../design/adapter-guide">adapter-guide</a> 的适配器形状增加 <code>plugin</code> 一项，能力声明增加来源；<a href="./../design/architecture">architecture</a> 的运行时层负责按来源选择，核心增加内置能力。</li><li><a href="https://github.com/yiyisf/laoshi/blob/main/docs/extraction/plan.md" target="_blank" rel="noreferrer">plan</a> 新增 dsh 适配器里程碑，内置能力并入 M2。</li><li>契约修订（决定 5）属于格式变更，按 <a href="./../contracts/agent-runtime">contracts/agent-runtime.md</a> 末尾的规则，与实现、迁移和 CHANGELOG 一起提交。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/laoshi/blob/main/docs/adr/0008-capability-sources-and-platform-plugin.md">docs/adr/0008-capability-sources-and-platform-plugin.md</a> 生成。<a href="https://github.com/yiyisf/laoshi/edit/main/docs/adr/0008-capability-sources-and-platform-plugin.md">在 GitHub 上编辑</a></p>',2)])])}const g=o(l,[["render",r]]);export{p as __pageData,g as default};
